{
  "name": "CineMuslim AI - Real-time Storyboard & Asset Generator",
  "description": "A sophisticated AI-powered filmmaking tool that generates professional storyboards, consistent visual assets, and high-quality voiceovers for short films and social media content.",
  "requestFramePermissions": []
