export interface Scene {
  id: number;
  script: string;
  visualPrompt1: string;
  videoPrompt1: string;
  visualPrompt2: string;
  videoPrompt2: string;
  imageUrl1?: string;
  imageUrl2?: string;
  audioUrl?: string;
  status: 'pending' | 'generating' | 'complete' | 'error';
  isImage1Regenerating?: boolean;
  isImage2Regenerating?: boolean;
  isAudioRegenerating?: boolean;
  isVisualPrompt1Regenerating?: boolean;
  isVisualPrompt2Regenerating?: boolean;
  isVideoPrompt1Regenerating?: boolean;
  isVideoPrompt2Regenerating?: boolean;
}

export interface StoryboardData {
  characterAnchor: string;
  scenes: Scene[];
}

export type VisualStyle = 'claymation' | 'realistic_clay' | 'lego' | 'cinematic' | 'anime' | 'islamic_art' | 'paper_cutout' | 'watercolor';
export type AspectRatio = '16:9' | '9:16' | '1:1';
export type VoiceName = 'Fenrir' | 'Puck' | 'Kore' | 'Aoede' | 'Zephyr';

export function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

/**
 * Converts raw PCM base64 data to a WAV Blob URL for playback.
 */
export const pcmToWav = (base64PCM: string, sampleRate: number = 24000): string | null => {
  try {
    const binaryString = atob(base64PCM);
    const len = binaryString.length;
    const adjustedLen = len % 2 === 0 ? len : len - 1;
    const buffer = new ArrayBuffer(adjustedLen);
    const view = new Uint8Array(buffer);
    for (let i = 0; i < adjustedLen; i++) {
      view[i] = binaryString.charCodeAt(i);
    }
    const pcmData = new Int16Array(buffer);

    const wavBuffer = new ArrayBuffer(44 + pcmData.length * 2);
    const viewWav = new DataView(wavBuffer);

    const writeString = (view: DataView, offset: number, string: string) => {
      for (let i = 0; i < string.length; i++) {
        view.setUint8(offset + i, string.charCodeAt(i));
      }
    };

    writeString(viewWav, 0, 'RIFF');
    viewWav.setUint32(4, 36 + pcmData.length * 2, true);
    writeString(viewWav, 8, 'WAVE');
    writeString(viewWav, 12, 'fmt ');
    viewWav.setUint32(16, 16, true);
    viewWav.setUint16(20, 1, true);
    viewWav.setUint16(22, 1, true);
    viewWav.setUint32(24, sampleRate, true);
    viewWav.setUint32(28, sampleRate * 2, true);
    viewWav.setUint16(32, 2, true);
    viewWav.setUint16(34, 16, true);
    writeString(viewWav, 36, 'data');
    viewWav.setUint32(40, pcmData.length * 2, true);

    const pcmView = new Int16Array(wavBuffer, 44);
    pcmView.set(pcmData);

    const blob = new Blob([wavBuffer], { type: 'audio/wav' });
    return URL.createObjectURL(blob);
  } catch (e) {
    console.error("Error converting audio:", e);
    return null;
  }
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { pcmToWav } from "../utils/audioUtils";
import { VisualStyle, AspectRatio, VoiceName } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeCharacterImage = async (base64Image: string, mimeType: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { text: "Analyze this character image in extreme detail for use as an image generation prompt. Describe: Physical appearance, Clothing (colors, style), Face, Hair, Accessories, and Body Type. Focus ONLY on visual details. Output a single dense paragraph." },
        { inlineData: { data: base64Image, mimeType } }
      ]
    }
  });
  return response.text || "";
};

export const generateStoryboard = async (
  story: string, 
  sceneCount: number, 
  style: VisualStyle, 
  language: string, 
  manualAnchor: string
): Promise<any> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Act as a professional film director. Break down this story into exactly ${sceneCount} distinct scenes.
    INPUTS: Story: "${story}", Style: "${style}", Language: "${language}".
    ${manualAnchor ? `CRITICAL: You MUST use this character description for 'characterAnchor': "${manualAnchor}"` : `Task: Establish one 'characterAnchor' which is a visual description of the main character.`}

    For each scene, provide a script (max 15 words) and two visual prompts (Action + Background) and two video motion prompts.
    Output ONLY a JSON object: { "characterAnchor": "string", "scenes": [{ "id": number, "script": "string", "visualPrompt1": "string", "videoPrompt1": "string", "visualPrompt2": "string", "videoPrompt2": "string" }] }`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          characterAnchor: { type: Type.STRING },
          scenes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                script: { type: Type.STRING },
                visualPrompt1: { type: Type.STRING },
                videoPrompt1: { type: Type.STRING },
                visualPrompt2: { type: Type.STRING },
                videoPrompt2: { type: Type.STRING }
              },
              required: ["id", "script", "visualPrompt1", "videoPrompt1", "visualPrompt2", "videoPrompt2"]
            }
          }
        },
        required: ["characterAnchor", "scenes"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

export const generateImage = async (
  prompt: string, 
  anchor: string, 
  style: VisualStyle, 
  aspectRatio: AspectRatio
): Promise<string> => {
  const stylePrefixes: Record<VisualStyle, string> = {
    claymation: "Claymation style, stop-motion animation, made of plasticine, chunky clay shapes, soft studio lighting, fingerprints visible",
    realistic_clay: "Hyperrealistic clay sculpture diorama, visible handmade textures, cinematic lighting, realistic proportions",
    lego: "Lego style, lego minifigures, built of lego bricks, vibrant plastic colors, 3d render",
    cinematic: "Cinematic, photorealistic, 8k resolution, dramatic lighting",
    anime: "Anime style, Studio Ghibli inspired, cel shaded, vibrant colors",
    islamic_art: "Islamic geometric patterns, gold and teal color palette, vector art style",
    paper_cutout: "Paper cutout art, layered paper, depth of field, craft aesthetic",
    watercolor: "Watercolor painting, soft strokes, pastel colors, artistic"
  };

  const fullPrompt = `${stylePrefixes[style]}, ${anchor ? `${anchor}, ` : ''}${prompt}, high quality, masterpiece, no text, no watermark`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: fullPrompt }] },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No image generated");
};

export const generateAudio = async (text: string, voiceName: VoiceName): Promise<string | null> => {
  if (!text) return null;
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-preview-tts',
    contents: [{ parts: [{ text: text.trim() }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voiceName }
        }
      }
    }
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio ? pcmToWav(base64Audio) : null;
};

import React, { useState, useRef, useCallback } from 'react';
import { 
  Clapperboard, Wand2, RefreshCw, AlertCircle, Play, Pause, Download, 
  ImageIcon, Layers, Smartphone, Monitor, Mic, Trash2, ImagePlus, Check,
  FileText, Archive, FileAudio, Users, Focus, Globe, Pencil, Save, Video,
  Search, Info
} from 'lucide-react';
import { Scene, VisualStyle, AspectRatio, VoiceName } from './types';
import * as geminiService from './services/geminiService';
import SceneCard from './components/SceneCard';

const App: React.FC = () => {
  const [story, setStory] = useState("");
  const [style, setStyle] = useState<VisualStyle>("claymation");
  const [ratio, setRatio] = useState<AspectRatio>("16:9");
  const [sceneCount, setSceneCount] = useState(3);
  const [voice, setVoice] = useState<VoiceName>("Fenrir");
  const [language, setLanguage] = useState("id");
  const [characterMode, setCharacterMode] = useState("with_char");
  const [targetAudience, setTargetAudience] = useState("children");

  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isAnalyzingImage, setIsAnalyzingImage] = useState(false);
  const [characterAnchor, setCharacterAnchor] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      setUploadedImage(reader.result as string);
      setIsAnalyzingImage(true);
      try {
        const description = await geminiService.analyzeCharacterImage(base64, file.type);
        setCharacterAnchor(description);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze character image.");
      } finally {
        setIsAnalyzingImage(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
    setCharacterAnchor("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const generateFullFilm = async () => {
    if (!story.trim()) return;
    setIsProcessing(true);
    setError(null);
    setScenes([]);
    setStatusMessage("Planning storyboard...");

    try {
      const storyboard = await geminiService.generateStoryboard(
        story, 
        sceneCount, 
        style, 
        language, 
        characterMode === 'with_char' ? characterAnchor : ""
      );

      const anchor = storyboard.characterAnchor || characterAnchor;
      setCharacterAnchor(anchor);

      const initialScenes = storyboard.scenes.map((s: any) => ({
        ...s,
        status: 'pending' as const
      }));
      setScenes(initialScenes);

      for (let i = 0; i < initialScenes.length; i++) {
        const scene = initialScenes[i];
        setScenes(prev => prev.map(s => s.id === scene.id ? { ...s, status: 'generating' } : s));
        setStatusMessage(`Generating assets for Scene ${scene.id}...`);

        const [img1, img2, audio] = await Promise.all([
          geminiService.generateImage(scene.visualPrompt1, anchor, style, ratio),
          geminiService.generateImage(scene.visualPrompt2, anchor, style, ratio),
          geminiService.generateAudio(scene.script, voice)
        ]);

        setScenes(prev => prev.map(s => s.id === scene.id ? { 
          ...s, 
          status: 'complete',
          imageUrl1: img1,
          imageUrl2: img2,
          audioUrl: audio || undefined
        } : s));
      }

      setStatusMessage("Project Completed!");
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setIsProcessing(false);
    }
  };

  const regenerateSceneImage = async (sceneId: number, prompt: string, index: number) => {
    const loadingKey = index === 1 ? 'isImage1Regenerating' : 'isImage2Regenerating';
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: true } : s));

    try {
      const url = await geminiService.generateImage(prompt, characterAnchor, style, ratio);
      setScenes(prev => prev.map(s => s.id === sceneId ? {
        ...s,
        [index === 1 ? 'imageUrl1' : 'imageUrl2']: url,
        [loadingKey]: false
      } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: false } : s));
    }
  };

  const regenerateSceneAudio = async (sceneId: number, script: string) => {
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: true } : s));
    try {
      const url = await geminiService.generateAudio(script, voice);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, audioUrl: url || undefined, isAudioRegenerating: false } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: false } : s));
    }
  };

  const downloadAllPrompts = () => {
    let content = `CineMuslim AI Project: ${story}\n\n`;
    content += `Style: ${style} | Ratio: ${ratio} | Voice: ${voice}\n`;
    content += `Character Description: ${characterAnchor}\n`;
    content += `=================================================\n\n`;
    scenes.forEach(s => {
      content += `[SCENE ${s.id}]\nScript: ${s.script}\nVisual A: ${s.visualPrompt1}\nVideo A: ${s.videoPrompt1}\n\n`;
    });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `storyboard-${Date.now()}.txt`;
    a.click();
  };

  const downloadAsZip = async (type: 'image' | 'audio') => {
    setIsZipping(true);
    try {
      // @ts-ignore
      const zip = new window.JSZip();
      const folder = zip.folder(type === 'image' ? 'Images' : 'Audio');

      for (const scene of scenes) {
        if (type === 'image') {
          if (scene.imageUrl1) {
            const data1 = scene.imageUrl1.split(',')[1];
            folder.file(`scene-${scene.id}-a.png`, data1, { base64: true });
          }
          if (scene.imageUrl2) {
            const data2 = scene.imageUrl2.split(',')[1];
            folder.file(`scene-${scene.id}-b.png`, data2, { base64: true });
          }
        } else if (type === 'audio' && scene.audioUrl) {
          const res = await fetch(scene.audioUrl);
          const blob = await res.blob();
          folder.file(`scene-${scene.id}.wav`, blob);
        }
      }

      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `cinemuslim-${type}-${Date.now()}.zip`;
      a.click();
    } catch (err) {
      alert("Zip creation failed");
    } finally {
      setIsZipping(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-emerald-500/30">
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-700 rounded-lg flex items-center justify-center shadow-lg shadow-emerald-500/20">
              <Clapperboard className="text-white" size={20} />
            </div>
            <div>
              <h1 className="font-bold text-xl text-white tracking-tight">CineMuslim AI</h1>
              <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">Generative Storyboard Studio</p>
            </div>
          </div>
          <div className="flex gap-4">
             <div className="hidden md:flex items-center gap-2 text-xs text-slate-400 bg-slate-800/50 px-3 py-1.5 rounded-full border border-slate-700">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                Gemini Multi-Modal Engine Active
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-6 grid lg:grid-cols-12 gap-8">
        {/* Sidebar Configuration */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-2xl">
            <h2 className="text-lg font-semibold text-white mb-6 flex items-center gap-2">
              <Wand2 className="text-emerald-500" size={18} />
              Film Configuration
            </h2>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Story Idea / Topic</label>
                <textarea 
                  value={story}
                  onChange={(e) => setStory(e.target.value)}
                  className="w-full h-32 bg-slate-800 border border-slate-700 rounded-xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none resize-none placeholder-slate-600 transition-all text-sm leading-relaxed"
                  placeholder="e.g. A young boy learns the importance of honesty while playing with his friends in a sunny garden..."
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Visual Style</label>
                  <select 
                    value={style}
                    onChange={(e) => setStyle(e.target.value as VisualStyle)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                  >
                    <option value="claymation">Claymation</option>
                    <option value="realistic_clay">Fine Art Clay</option>
                    <option value="lego">Lego World</option>
                    <option value="cinematic">Cinematic 8K</option>
                    <option value="anime">Anime (Ghibli)</option>
                    <option value="watercolor">Watercolor</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Aspect Ratio</label>
                  <select 
                    value={ratio}
                    onChange={(e) => setRatio(e.target.value as AspectRatio)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                  >
                    <option value="16:9">16:9 Landscape</option>
                    <option value="9:16">9:16 Portrait</option>
                    <option value="1:1">1:1 Square</option>
                  </select>
                </div>
              </div>

              {/* Character consistency block */}
              <div className="bg-slate-800/40 p-4 rounded-xl border border-slate-800 space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                    <Focus size={14} /> Character Anchor
                  </label>
                  {uploadedImage && (
                    <button onClick={clearUploadedImage} className="text-[10px] text-red-400 hover:text-red-300 flex items-center gap-1 uppercase font-bold">
                      <Trash2 size={10} /> Reset
                    </button>
                  )}
                </div>

                {!uploadedImage ? (
                  <div className="relative group">
                    <input 
                      type="file" 
                      ref={fileInputRef}
                      onChange={handleImageUpload}
                      accept="image/*"
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                    />
                    <div className="flex flex-col items-center justify-center p-6 border-2 border-dashed border-slate-700 rounded-xl group-hover:border-emerald-500/50 group-hover:bg-slate-800 transition-all text-center">
                      {isAnalyzingImage ? (
                        <RefreshCw className="animate-spin text-emerald-500 mb-2" size={24} />
                      ) : (
                        <ImagePlus className="text-slate-500 group-hover:text-emerald-500 mb-2" size={24} />
                      )}
                      <span className="text-xs font-medium text-slate-400">
                        {isAnalyzingImage ? "AI Analyzing Character..." : "Upload Character (Optional)"}
                      </span>
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-3 items-center bg-slate-900/50 p-2 rounded-lg border border-slate-800">
                    <img src={uploadedImage} alt="ref" className="w-12 h-12 rounded object-cover border border-slate-700" />
                    <div className="flex-1 min-w-0">
                      <div className="text-[10px] text-emerald-400 font-bold uppercase mb-1 flex items-center gap-1">
                        <Check size={10} /> Character Identified
                      </div>
                      <p className="text-[10px] text-slate-500 line-clamp-2 italic leading-tight">
                        {characterAnchor}
                      </p>
                    </div>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Language</label>
                  <select 
                    value={language}
                    onChange={(e) => setLanguage(e.target.value)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-sm outline-none"
                  >
                    <option value="id">Indonesian</option>
                    <option value="en">English</option>
                    <option value="ms">Malay</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Voice Tone</label>
                  <select 
                    value={voice}
                    onChange={(e) => setVoice(e.target.value as VoiceName)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-2.5 text-sm outline-none"
                  >
                    <option value="Fenrir">Ustadz (Deep)</option>
                    <option value="Kore">Sister (Soft)</option>
                    <option value="Puck">Young (Energetic)</option>
                    <option value="Aoede">Child (Cheerful)</option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Number of Scenes</label>
                <div className="flex gap-2">
                  {[1, 3, 5, 8].map(n => (
                    <button 
                      key={n}
                      onClick={() => setSceneCount(n)}
                      className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${sceneCount === n ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'}`}
                    >
                      {n} {n === 1 ? 'Scene' : 'Scenes'}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={generateFullFilm}
                disabled={isProcessing || !story.trim() || isAnalyzingImage}
                className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-3 shadow-xl transition-all
                  ${isProcessing ? 'bg-slate-800 text-slate-500 cursor-not-allowed' : 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-emerald-900/20'}
                `}
              >
                {isProcessing ? (
                  <><RefreshCw className="animate-spin" size={18} /> {statusMessage}</>
                ) : (
                  <><Wand2 size={18} /> Generate Film Assets</>
                )}
              </button>

              {error && (
