import React, { useState, useRef, useEffect } from 'react';
import { 
  Play, Pause, RefreshCw, Download, Pencil, Save, Copy, Check, Video, Wand2, Info
} from 'lucide-react';
import { Scene, AspectRatio } from '../types';

interface SceneCardProps {
  scene: Scene;
  index: number;
  ratio: AspectRatio;
  onRegenerateImage: (idx: number) => void;
  onRegenerateAudio: () => void;
  onUpdateScript: (text: string) => void;
}

const SceneCard: React.FC<SceneCardProps> = ({ 
  scene, index, ratio, onRegenerateImage, onRegenerateAudio, onUpdateScript 
}) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [localScript, setLocalScript] = useState(scene.script);
  const audioRef = useRef<HTMLAudioElement>(null);

  const ratioClasses: Record<AspectRatio, string> = {
    '16:9': 'aspect-video',
    '9:16': 'aspect-[9/16] max-w-[280px]',
    '1:1': 'aspect-square max-w-[400px]'
  };

  useEffect(() => {
    if (!isEditing) setLocalScript(scene.script);
  }, [scene.script, isEditing]);

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const saveScript = () => {
    onUpdateScript(localScript);
    setIsEditing(false);
  };

  const copyPrompt = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const renderImage = (imgUrl: string | undefined, isRegen: boolean | undefined, idx: number, prompt: string) => {
    return (
      <div className="flex-1 space-y-3">
        <div className={`relative group overflow-hidden rounded-2xl bg-slate-950 border border-slate-800 ${ratioClasses[ratio]} shadow-lg`}>
          <div className="absolute top-3 left-3 z-20 flex gap-2">
            <span className="bg-black/70 backdrop-blur px-2 py-0.5 rounded text-[10px] text-white font-mono border border-white/10">
              SHOT {idx === 1 ? 'A' : 'B'}
            </span>
          </div>

          <div className="absolute top-3 right-3 z-30 opacity-0 group-hover:opacity-100 transition-all flex flex-col gap-2">
            <button 
              onClick={() => onRegenerateImage(idx)}
              disabled={isRegen}
              className="p-2 bg-black/80 text-white rounded-full hover:bg-emerald-600 transition-all border border-white/20"
            >
              <RefreshCw size={14} className={isRegen ? 'animate-spin' : ''} />
            </button>
            {imgUrl && (
              <a href={imgUrl} download={`scene-${scene.id}-${idx}.png`} className="p-2 bg-black/80 text-white rounded-full hover:bg-blue-600 transition-all border border-white/20">
                <Download size={14} />
              </a>
            )}
          </div>

          {isRegen || scene.status === 'generating' ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/90 z-10">
              <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin mb-2"></div>
              <span className="text-[10px] text-emerald-500 uppercase font-bold tracking-widest animate-pulse">Rendering...</span>
            </div>
          ) : imgUrl ? (
            <img src={imgUrl} alt={`Scene ${scene.id}`} className="w-full h-full object-cover" />
          ) : (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-700">
              <RefreshCw size={24} className="mb-2 opacity-20" />
              <span className="text-[10px] uppercase font-bold tracking-widest">Pending</span>
            </div>
          )}
        </div>

        <div className="space-y-2">
           <div className="flex justify-between items-center">
             <label className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1">
               <Wand2 size={10} /> Image Prompt
             </label>
             <button onClick={() => copyPrompt(prompt)} className="text-[10px] text-emerald-500 hover:text-emerald-400 font-bold flex items-center gap-1">
               <Copy size={10} /> Copy
             </button>
           </div>
           <div className="bg-slate-900/80 p-2.5 rounded-lg border border-slate-800 text-[10px] text-slate-400 line-clamp-2 hover:line-clamp-none transition-all font-mono leading-relaxed italic">
             {prompt}
           </div>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-900/80 border border-slate-800 rounded-3xl p-6 shadow-xl hover:border-slate-700 transition-all relative">
      <div className="flex flex-col gap-6">
        {/* Header Section */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <span className="bg-emerald-600/20 text-emerald-500 border border-emerald-500/30 text-xs font-black px-4 py-1.5 rounded-full uppercase tracking-widest shadow-lg shadow-emerald-500/10">
              Scene {index}
            </span>
            <div className="flex items-center gap-2 bg-slate-800/80 rounded-full p-1 pr-4 border border-slate-700">
              <button 
                onClick={toggleAudio}
                disabled={!scene.audioUrl}
                className={`w-8 h-8 flex items-center justify-center rounded-full transition-all ${scene.audioUrl ? 'bg-emerald-600 text-white hover:bg-emerald-500' : 'bg-slate-700 text-slate-500 cursor-not-allowed'}`}
              >
                {isPlaying ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" className="ml-0.5" />}
              </button>
              <div className="w-px h-4 bg-slate-700 mx-1"></div>
              <button 
                onClick={onRegenerateAudio}
                disabled={scene.isAudioRegenerating}
                className="text-slate-400 hover:text-white transition-all"
                title="Regenerate Voice"
              >
                <RefreshCw size={14} className={scene.isAudioRegenerating ? 'animate-spin' : ''} />
              </button>
              {scene.audioUrl && (
                <a href={scene.audioUrl} download={`voice-${scene.id}.wav`} className="text-slate-400 hover:text-white transition-all ml-1">
                  <Download size={14} />
                </a>
              )}
            </div>
          </div>

          <div className="flex items-center gap-2">
            {isEditing ? (
              <button onClick={saveScript} className="text-emerald-500 hover:text-emerald-400 text-xs font-bold flex items-center gap-1 bg-emerald-500/10 px-3 py-1.5 rounded-lg border border-emerald-500/20">
                <Save size={14} /> Save Script
              </button>
            ) : (
              <button onClick={() => setIsEditing(true)} className="text-slate-500 hover:text-white text-xs font-bold flex items-center gap-1 transition-all">
                <Pencil size={14} /> Edit Script
              </button>
            )}
          </div>
        </div>

        {/* Script Block */}
        <div className="bg-slate-950/40 p-5 rounded-2xl border border-slate-800/50 relative">
          <div className="absolute -top-2 left-4 px-2 bg-slate-950 text-[9px] font-bold text-slate-600 uppercase tracking-[0.2em]">Narrator Script</div>
          {isEditing ? (
            <textarea 
              value={localScript}
              onChange={(e) => setLocalScript(e.target.value)}
              className="w-full bg-transparent border-none focus:ring-0 text-slate-200 text-base leading-relaxed italic resize-none p-0"
              rows={2}
              autoFocus
            />
          ) : (
            <p className="text-slate-300 text-base leading-relaxed italic">
              "{scene.script || "Script pending generation..."}"
            </p>
          )}
        </div>

        {/* Visuals Container */}
        <div className="flex flex-col lg:flex-row gap-8">
          {renderImage(scene.imageUrl1, scene.isImage1Regenerating, 1, scene.visualPrompt1)}
          {renderImage(scene.imageUrl2, scene.isImage2Regenerating, 2, scene.visualPrompt2)}
        </div>
      </div>

      <audio ref={audioRef} src={scene.audioUrl} onEnded={() => setIsPlaying(false)} className="hidden" />
    </div>
  );
};

export default SceneCard;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { pcmToWav } from "../utils/audioUtils";
import { VisualStyle, AspectRatio, VoiceName } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeCharacterImage = async (base64Image: string, mimeType: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { text: "Analyze this character image in extreme detail. Describe: Age, modern clothing style, specific facial features, hair, and accessories. Focus on making the description suitable for a high-quality consistent image generation prompt. Output a single dense paragraph." },
        { inlineData: { data: base64Image, mimeType } }
      ]
    }
  });
  return response.text || "";
};

export const generateStoryboard = async (
  story: string, 
  sceneCount: number, 
  style: VisualStyle, 
  language: string, 
  manualAnchor: string
): Promise<any> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Act as a professional film director and character designer. Break down this story into exactly ${sceneCount} distinct scenes.
    INPUTS: Story: "${story}", Style: "${style}", Language: "${language}".

    CRITICAL CHARACTER INSTRUCTION: 
    Create a 'characterAnchor' that is DYNAMIC and MODERN. Unless the story is explicitly set in the past, the character should have contemporary features, modern stylish clothing (e.g., hoodies, sneakers, glasses, neat hijabs, or trendy outfits), and expressive faces. 
    AVOID: Primitive, prehistoric, or caveman-like aesthetics.

    ${manualAnchor ? `USE THIS SPECIFIC CHARACTER: "${manualAnchor}"` : `Task: Design one consistent 'characterAnchor' visual description.`}

    For each scene, provide a script and two visual prompts.
    Output ONLY a JSON object: { "characterAnchor": "string", "scenes": [{ "id": number, "script": "string", "visualPrompt1": "string", "videoPrompt1": "string", "visualPrompt2": "string", "videoPrompt2": "string" }] }`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          characterAnchor: { type: Type.STRING },
          scenes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                script: { type: Type.STRING },
                visualPrompt1: { type: Type.STRING },
                videoPrompt1: { type: Type.STRING },
                visualPrompt2: { type: Type.STRING },
                videoPrompt2: { type: Type.STRING }
              },
              required: ["id", "script", "visualPrompt1", "videoPrompt1", "visualPrompt2", "videoPrompt2"]
            }
          }
        },
        required: ["characterAnchor", "scenes"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

export const generateImage = async (
  prompt: string, 
  anchor: string, 
  style: VisualStyle, 
  aspectRatio: AspectRatio
): Promise<string> => {
  const stylePrefixes: Record<VisualStyle, string> = {
    claymation: "Modern 3D claymation style, professional stop-motion, high-quality plasticine, vibrant colors, clean finish, detailed modern props, studio lighting",
    realistic_clay: "Contemporary high-end clay sculpture, realistic facial expressions, modern attire, sharp details, cinematic lighting, 8k diorama",
    lego: "Modern Lego minifigures, detailed plastic textures, bright contemporary colors, high-resolution 3D render, sharp edges",
    cinematic: "Cinematic film still, photorealistic, modern fashion, dramatic lighting, 8k resolution, professional color grading",
    anime: "Modern high-quality anime, vibrant digital art style, expressive eyes, contemporary clothing, clean lines, beautiful backgrounds",
    islamic_art: "Modern Islamic digital illustration, minimalist geometric patterns, elegant teal and gold, clean vector style, contemporary aesthetic",
    paper_cutout: "Modern layered paper art, clean sharp edges, depth of field, vibrant contemporary colors, intricate craft",
    watercolor: "Modern watercolor illustration, soft blending, artistic strokes, contemporary subjects, high-quality paper texture"
  };

  const negativePrompt = "Avoid primitive, prehistoric, stone age, caveman, messy, blurry, low quality, deformed, old-fashioned clothing";
  const fullPrompt = `${stylePrefixes[style]}, ${anchor ? `${anchor}, ` : ''}${prompt}, ${negativePrompt}, highly detailed, professional masterpiece, no text`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: fullPrompt }] },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No image generated");
};

export const generateAudio = async (text: string, voiceName: VoiceName): Promise<string | null> => {
  if (!text) return null;
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-preview-tts',
    contents: [{ parts: [{ text: text.trim() }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voiceName }
        }
      }
    }
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio ? pcmToWav(base64Audio) : null;
};

import React, { useState, useRef, useCallback } from 'react';
import { 
  Clapperboard, Wand2, RefreshCw, AlertCircle, Play, Pause, Download, 
  ImageIcon, Layers, Smartphone, Monitor, Mic, Trash2, ImagePlus, Check,
  FileText, Archive, FileAudio, Users, Focus, Globe, Pencil, Save, Video,
  Search, Info
} from 'lucide-react';
import { Scene, VisualStyle, AspectRatio, VoiceName } from './types';
import * as geminiService from './services/geminiService';
import SceneCard from './components/SceneCard';

const App: React.FC = () => {
  const [story, setStory] = useState("");
  const [style, setStyle] = useState<VisualStyle>("claymation");
  const [ratio, setRatio] = useState<AspectRatio>("16:9");
  const [sceneCount, setSceneCount] = useState(3);
  const [voice, setVoice] = useState<VoiceName>("Fenrir");
  const [language, setLanguage] = useState("id");
  const [characterMode, setCharacterMode] = useState("with_char");
  const [targetAudience, setTargetAudience] = useState("children");

  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isAnalyzingImage, setIsAnalyzingImage] = useState(false);
  const [characterAnchor, setCharacterAnchor] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      setUploadedImage(reader.result as string);
      setIsAnalyzingImage(true);
      try {
        const description = await geminiService.analyzeCharacterImage(base64, file.type);
        setCharacterAnchor(description);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze character image.");
      } finally {
        setIsAnalyzingImage(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
    setCharacterAnchor("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const generateFullFilm = async () => {
    if (!story.trim()) return;
    setIsProcessing(true);
    setError(null);
    setScenes([]);
    setStatusMessage("Planning storyboard...");

    try {
      const storyboard = await geminiService.generateStoryboard(
        story, 
        sceneCount, 
        style, 
        language, 
        characterMode === 'with_char' ? characterAnchor : ""
      );

      const anchor = storyboard.characterAnchor || characterAnchor;
      setCharacterAnchor(anchor);

      const initialScenes = storyboard.scenes.map((s: any) => ({
        ...s,
        status: 'pending' as const
      }));
      setScenes(initialScenes);

      for (let i = 0; i < initialScenes.length; i++) {
        const scene = initialScenes[i];
        setScenes(prev => prev.map(s => s.id === scene.id ? { ...s, status: 'generating' } : s));
        setStatusMessage(`Generating assets for Scene ${scene.id}...`);

        const [img1, img2, audio] = await Promise.all([
          geminiService.generateImage(scene.visualPrompt1, anchor, style, ratio),
          geminiService.generateImage(scene.visualPrompt2, anchor, style, ratio),
          geminiService.generateAudio(scene.script, voice)
        ]);

        setScenes(prev => prev.map(s => s.id === scene.id ? { 
          ...s, 
          status: 'complete',
          imageUrl1: img1,
          imageUrl2: img2,
          audioUrl: audio || undefined
        } : s));
      }

      setStatusMessage("Project Completed!");
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setIsProcessing(false);
    }
  };

  const regenerateSceneImage = async (sceneId: number, prompt: string, index: number) => {
    const loadingKey = index === 1 ? 'isImage1Regenerating' : 'isImage2Regenerating';
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: true } : s));

    try {
      const url = await geminiService.generateImage(prompt, characterAnchor, style, ratio);
      setScenes(prev => prev.map(s => s.id === sceneId ? {
        ...s,
        [index === 1 ? 'imageUrl1' : 'imageUrl2']: url,
        [loadingKey]: false
      } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: false } : s));
    }
  };

  const regenerateSceneAudio = async (sceneId: number, script: string) => {
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: true } : s));
    try {
      const url = await geminiService.generateAudio(script, voice);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, audioUrl: url || undefined, isAudioRegenerating: false } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: false } : s));
    }
  };

  const downloadAllPrompts = () => {
    let content = `CineMuslim AI Project: ${story}\n\n`;
    content += `Style: ${style} | Ratio: ${ratio} | Voice: ${voice}\n`;
    content += `Character Description: ${characterAnchor}\n`;
    content += `=================================================\n\n`;
    scenes.forEach(s => {
      content += `[SCENE ${s.id}]\nScript: ${s.script}\nVisual A: ${s.visualPrompt1}\nVideo A: ${s.videoPrompt1}\n\n`;
    });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `storyboard-${Date.now()}.txt`;
    a.click();
  };

  const downloadAsZip = async (type: 'image' | 'audio') => {
    setIsZipping(true);
    try {
      // @ts-ignore
      const zip = new window.JSZip();
      const folder = zip.folder(type === 'image' ? 'Images' : 'Audio');

      for (const scene of scenes) {
        if (type === 'image') {
          if (scene.imageUrl1) {
            const data1 = scene.imageUrl1.split(',')[1];
            folder.file(`scene-${scene.id}-a.png`, data1, { base64: true });
          }
          if (scene.imageUrl2) {
            const data2 = scene.imageUrl2.split(',')[1];
            folder.file(`scene-${scene.id}-b.png`, data2, { base64: true });
          }
        } else if (type === 'audio' && scene.audioUrl) {
          const res = await fetch(scene.audioUrl);
          const blob = await res.blob();
          folder.file(`scene-${scene.id}.wav`, blob);
        }
      }

      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `cinemuslim-${type}-${Date.now()}.zip`;
      a.click();
    } catch (err) {
