                  </p>
                </div>
                <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
                  <button 
                    onClick={downloadAllPrompts}
                    disabled={isProcessing}
                    className="flex-none flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-xl text-xs font-bold disabled:opacity-50"
                  >
                    <FileText size={14} /> Prompts (TXT)
                  </button>
                  <button 
                    onClick={() => downloadAsZip('image')}
                    disabled={isProcessing || isZipping}
                    className="flex-none flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-xl text-xs font-bold disabled:opacity-50"
                  >
                    {isZipping ? <RefreshCw className="animate-spin" size={14} /> : <Archive size={14} />}
                    Images (ZIP)
                  </button>
                  <button 
                    onClick={() => downloadAsZip('audio')}
                    disabled={isProcessing || isZipping}
                    className="flex-none flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-xl text-xs font-bold disabled:opacity-50"
                  >
                    {isZipping ? <RefreshCw className="animate-spin" size={14} /> : <FileAudio size={14} />}
                    Audio (ZIP)
                  </button>
                </div>
              </div>

              <div className="space-y-12 pb-20">
                {scenes.map((scene, idx) => (
                  <SceneCard 
                    key={scene.id}
                    scene={scene}
                    index={idx + 1}
                    ratio={ratio}
                    onRegenerateImage={(imgIdx) => regenerateSceneImage(scene.id, imgIdx === 1 ? scene.visualPrompt1 : scene.visualPrompt2, imgIdx)}
                    onRegenerateAudio={() => regenerateSceneAudio(scene.id, scene.script)}
                    onUpdateScript={(text) => setScenes(prev => prev.map(s => s.id === scene.id ? { ...s, script: text } : s))}
                  />
                ))}

                {isProcessing && scenes.length < sceneCount && (
                  <div className="p-8 border-2 border-dashed border-slate-800 rounded-3xl animate-pulse flex flex-col items-center justify-center bg-slate-900/30">
                    <RefreshCw className="animate-spin text-slate-700 mb-4" size={32} />
                    <p className="text-slate-600 text-sm font-medium italic">Gemini is sketching your next scenes...</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { pcmToWav } from "../utils/audioUtils";
import { VisualStyle, AspectRatio, VoiceName } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeCharacterImage = async (base64Image: string, mimeType: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { text: "Analyze this character image in extreme detail. Describe: Age, modern clothing style, specific facial features, hair, and accessories. Focus on making the description suitable for a high-quality consistent image generation prompt. Output a single dense paragraph." },
        { inlineData: { data: base64Image, mimeType } }
      ]
    }
  });
  return response.text || "";
};

export const generateStoryboard = async (
  story: string, 
  sceneCount: number, 
  style: VisualStyle, 
  language: string, 
  manualAnchor: string,
  mode: 'with_char' | 'no_char'
): Promise<any> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Act as a professional film director and visual designer. Break down this story into exactly ${sceneCount} distinct scenes.
    INPUTS: Story: "${story}", Style: "${style}", Language: "${language}".

    PRODUCTION MODE: ${mode === 'with_char' ? 'Consistency (Single Character Focus)' : 'Dynamic (Focus on atmosphere and varied subjects)'}.

    ${mode === 'with_char' 
      ? `CRITICAL: You MUST establish a consistent 'characterAnchor'. ${manualAnchor ? `Use this: "${manualAnchor}"` : 'Design a modern, dynamic character description.'}` 
      : `CRITICAL: There is NO main character. Focus each scene description on unique environments, varied objects, or different people to keep the visuals random and interesting.`}

    For each scene, provide a script and two visual prompts.
    Output ONLY a JSON object: { "characterAnchor": "string", "scenes": [{ "id": number, "script": "string", "visualPrompt1": "string", "videoPrompt1": "string", "visualPrompt2": "string", "videoPrompt2": "string" }] }`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          characterAnchor: { type: Type.STRING },
          scenes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                script: { type: Type.STRING },
                visualPrompt1: { type: Type.STRING },
                videoPrompt1: { type: Type.STRING },
                visualPrompt2: { type: Type.STRING },
                videoPrompt2: { type: Type.STRING }
              },
              required: ["id", "script", "visualPrompt1", "videoPrompt1", "visualPrompt2", "videoPrompt2"]
            }
          }
        },
        required: ["characterAnchor", "scenes"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

export const generateImage = async (
  prompt: string, 
  anchor: string, 
  style: VisualStyle, 
  aspectRatio: AspectRatio
): Promise<string> => {
  const stylePrefixes: Record<VisualStyle, string> = {
    claymation: "Modern 3D claymation style, professional stop-motion, high-quality plasticine, vibrant colors, clean finish, detailed modern props, studio lighting",
    realistic_clay: "Contemporary high-end clay sculpture, realistic facial expressions, modern attire, sharp details, cinematic lighting, 8k diorama",
    lego: "Modern Lego minifigures, detailed plastic textures, bright contemporary colors, high-resolution 3D render, sharp edges",
    cinematic: "Cinematic film still, photorealistic, modern fashion, dramatic lighting, 8k resolution, professional color grading",
    anime: "Modern high-quality anime, vibrant digital art style, expressive eyes, contemporary clothing, clean lines, beautiful backgrounds",
    islamic_art: "Modern Islamic digital illustration, minimalist geometric patterns, elegant teal and gold, clean vector style, contemporary aesthetic",
    paper_cutout: "Modern layered paper art, clean sharp edges, depth of field, vibrant contemporary colors, intricate craft",
    watercolor: "Modern watercolor illustration, soft blending, artistic strokes, contemporary subjects, high-quality paper texture"
  };

  const negativePrompt = "Avoid primitive, prehistoric, stone age, caveman, messy, blurry, low quality, deformed, old-fashioned clothing";
  // Jika anchor ada (Mode With Char), gunakan. Jika tidak, abaikan untuk hasil random.
  const fullPrompt = `${stylePrefixes[style]}, ${anchor ? `${anchor}, ` : ''}${prompt}, ${negativePrompt}, highly detailed, professional masterpiece, no text`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: fullPrompt }] },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No image generated");
};

export const generateAudio = async (text: string, voiceName: VoiceName): Promise<string | null> => {
  if (!text) return null;
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-preview-tts',
    contents: [{ parts: [{ text: text.trim() }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voiceName }
        }
      }
    }
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio ? pcmToWav(base64Audio) : null;
};

import React, { useState, useRef, useCallback } from 'react';
import { 
  Clapperboard, Wand2, RefreshCw, AlertCircle, Play, Pause, Download, 
  ImageIcon, Layers, Smartphone, Monitor, Mic, Trash2, ImagePlus, Check,
  FileText, Archive, FileAudio, Users, Focus, Globe, Pencil, Save, Video,
  Search, Info
} from 'lucide-react';
import { Scene, VisualStyle, AspectRatio, VoiceName } from './types';
import * as geminiService from './services/geminiService';
import SceneCard from './components/SceneCard';

const App: React.FC = () => {
  const [story, setStory] = useState("");
  const [style, setStyle] = useState<VisualStyle>("claymation");
  const [ratio, setRatio] = useState<AspectRatio>("16:9");
  const [sceneCount, setSceneCount] = useState(3);
  const [voice, setVoice] = useState<VoiceName>("Fenrir");
  const [language, setLanguage] = useState("id");
  const [characterMode, setCharacterMode] = useState<'with_char' | 'no_char'>("with_char");

  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [isAnalyzingImage, setIsAnalyzingImage] = useState(false);
  const [characterAnchor, setCharacterAnchor] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      setUploadedImage(reader.result as string);
      setIsAnalyzingImage(true);
      try {
        const description = await geminiService.analyzeCharacterImage(base64, file.type);
        setCharacterAnchor(description);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze character image.");
      } finally {
        setIsAnalyzingImage(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const clearUploadedImage = () => {
    setUploadedImage(null);
    setCharacterAnchor("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const generateFullFilm = async () => {
    if (!story.trim()) return;
    setIsProcessing(true);
    setError(null);
    setScenes([]);
    setStatusMessage("Planning storyboard...");

    try {
      // 1. Generate Storyboard structure
      const storyboard = await geminiService.generateStoryboard(
        story, 
        sceneCount, 
        style, 
        language, 
        characterMode === 'with_char' ? characterAnchor : "",
        characterMode
      );

      // 2. Set Anchor for production
      const finalAnchor = characterMode === 'with_char' ? (storyboard.characterAnchor || characterAnchor) : "";
      if (characterMode === 'with_char') setCharacterAnchor(finalAnchor);

      const initialScenes = storyboard.scenes.map((s: any) => ({
        ...s,
        status: 'pending' as const
      }));
      setScenes(initialScenes);

      // 3. Sequential production of assets
      for (let i = 0; i < initialScenes.length; i++) {
        const scene = initialScenes[i];
        setScenes(prev => prev.map(s => s.id === scene.id ? { ...s, status: 'generating' } : s));
        setStatusMessage(`Generating assets for Scene ${scene.id}...`);

        const [img1, img2, audio] = await Promise.all([
          geminiService.generateImage(scene.visualPrompt1, finalAnchor, style, ratio),
          geminiService.generateImage(scene.visualPrompt2, finalAnchor, style, ratio),
          geminiService.generateAudio(scene.script, voice)
        ]);

        setScenes(prev => prev.map(s => s.id === scene.id ? { 
          ...s, 
          status: 'complete',
          imageUrl1: img1,
          imageUrl2: img2,
          audioUrl: audio || undefined
        } : s));
      }

      setStatusMessage("Project Completed!");
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setIsProcessing(false);
    }
  };

  const regenerateSceneImage = async (sceneId: number, prompt: string, index: number) => {
    const loadingKey = index === 1 ? 'isImage1Regenerating' : 'isImage2Regenerating';
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: true } : s));

    try {
      const finalAnchor = characterMode === 'with_char' ? characterAnchor : "";
      const url = await geminiService.generateImage(prompt, finalAnchor, style, ratio);
      setScenes(prev => prev.map(s => s.id === sceneId ? {
        ...s,
        [index === 1 ? 'imageUrl1' : 'imageUrl2']: url,
        [loadingKey]: false
      } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, [loadingKey]: false } : s));
    }
  };

  const regenerateSceneAudio = async (sceneId: number, script: string) => {
    setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: true } : s));
    try {
      const url = await geminiService.generateAudio(script, voice);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, audioUrl: url || undefined, isAudioRegenerating: false } : s));
    } catch (err) {
      console.error(err);
      setScenes(prev => prev.map(s => s.id === sceneId ? { ...s, isAudioRegenerating: false } : s));
    }
  };

  const downloadAllPrompts = () => {
    let content = `CineMuslim AI Project: ${story}\n\n`;
    content += `Mode: ${characterMode === 'with_char' ? 'With Character' : 'Dynamic/Random'}\n`;
    content += `Style: ${style} | Ratio: ${ratio} | Voice: ${voice}\n`;
    if (characterMode === 'with_char') content += `Character Anchor: ${characterAnchor}\n`;
    content += `=================================================\n\n`;
    scenes.forEach(s => {
      content += `[SCENE ${s.id}]\nScript: ${s.script}\nPrompt A: ${s.visualPrompt1}\nPrompt B: ${s.visualPrompt2}\n\n`;
    });
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `storyboard-${Date.now()}.txt`;
    a.click();
  };

  const downloadAsZip = async (type: 'image' | 'audio') => {
    setIsZipping(true);
    try {
      // @ts-ignore
      const zip = new window.JSZip();
      const folder = zip.folder(type === 'image' ? 'Images' : 'Audio');

      for (const scene of scenes) {
        if (type === 'image') {
          if (scene.imageUrl1) {
            const data1 = scene.imageUrl1.split(',')[1];
            folder.file(`scene-${scene.id}-a.png`, data1, { base64: true });
          }
          if (scene.imageUrl2) {
            const data2 = scene.imageUrl2.split(',')[1];
            folder.file(`scene-${scene.id}-b.png`, data2, { base64: true });
          }
        } else if (type === 'audio' && scene.audioUrl) {
          const res = await fetch(scene.audioUrl);
          const blob = await res.blob();
          folder.file(`scene-${scene.id}.wav`, blob);
        }
      }

      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `cinemuslim-${type}-${Date.now()}.zip`;
      a.click();
    } catch (err) {
      alert("Zip creation failed");
    } finally {
      setIsZipping(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-emerald-500/30">
